resource "aws_iam_role" "vendor_audit_delegation" {
  name = "VendorSecurityAuditorRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::123456789012:root" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.vendor_shared_secret
          }
        }
      }
    ]
  })
}

