resource "azuread_conditional_access_policy" "require_mfa" {
  display_name = "Enforce-MFA-Administrative-Roles"
  state        = "enabled"
  conditions {
    client_app_types = ["all"]
    users {
      included_roles = ["62e90394-69f5-4237-9190-012177145e10"] # Global Admin
    }
  }
  grant_controls {
    operator          = "OR"
    built_in_controls = ["mfa"]
  }
}

resource "azuread_conditional_access_policy" "block_legacy" {
  display_name = "Block-Legacy-Authentication"
  state        = "enabled"
  conditions {
    client_app_types = ["exchangeActiveSync", "other"]
    users { included_users = ["All"] }
  }
  grant_controls {
    built_in_controls = ["block"]
  }
}

resource "azuread_conditional_access_policy" "phishing_resistant" {
  display_name = "Enforce-Phishing-Resistant-MFA"
  state        = "enabled"
  grant_controls {
    authentication_strength_policy_id = "00000000-0000-0000-0000-000000000004"
  }
}

resource "azurerm_pim_eligible_role_assignment" "admin_pim" {
  scope              = "/subscriptions/${var.subscription_id}"
  role_definition_id = "/subscriptions/${var.subscription_id}/providers/Microsoft.Authorization/roleDefinitions/${var.role_id}"
  principal_id       = var.admin_user_id
  schedule {
    start_date_time = "2026-01-01T00:00:00Z"
    expiration {
      duration_hours = 8
    }
  }
}

resource "azurerm_storage_account" "secure_storage" {
  name                     = "secvault${var.env}"
  resource_group_name      = var.rg_name
  location                 = var.location
  account_tier             = "Standard"
  account_replication_type = "GRS"
  identity { type = "UserAssigned" }
}

resource "azurerm_storage_account_customer_managed_key" "cmk" {
  storage_account_id = azurerm_storage_account.secure_storage.id
  key_vault_id       = var.key_vault_id
  key_name           = "storage-encryption-key"
}

resource "azurerm_storage_account" "private_storage" {
  name                            = "privatevault${var.env}"
  allow_nested_items_to_be_public = false
  min_tls_version                 = "TLS1_2"
  enable_https_traffic_only       = true
}

resource "azurerm_storage_account" "tls_enforced" {
